def twoSum(nums, target):
    seen = {}                       # 值到下标
    for i, x in enumerate(nums):
        need = target - x           # 需要的补数
        if need in seen:
            return [seen[need], i]
        seen[x] = i                 # 先查后存防重复用
    return []

from collections import defaultdict
def groupAnagrams(strs):
    groups = defaultdict(list)
    for w in strs:
        key = ''.join(sorted(w))    # 排序串作分组键
        groups[key].append(w)
    return list(groups.values())

