def longestConsecutive(nums):
    s = set(nums)
    best = 0
    for x in s:
        if x - 1 not in s:      # 只从序列起点开始数
            y = x
            while y + 1 in s:
                y += 1
            best = max(best, y - x + 1)
    return best
